#include <iostream>
#include <vector>
#include <string>
using namespace std;

const long long MOD = 1000000007LL;

long long power(long long a, long long b) {
    if (b == 0) {
        return 1;
    }
    return a * power(a, b - 1) % MOD;
}

int main() {
    long long a;
    long long b;
    cin >> a >> b;

    cout << power(a, b) << endl;

    return 0;
}

