import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    static long power(long a, long b) {
        if (b == 0) {
            return 1;
        }
        return a * power(a, b - 1) % MOD;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();

        System.out.println(power(a, b));
    }
}
